import type { IncomingMessage } from "node:http";

export const MAX_BODY = 1024 * 1024;
export class TooLarge extends Error {}

export const readBody = async (req: IncomingMessage, limit = MAX_BODY) => {
  const chunks: Buffer[] = [];
  let size = 0;
  for await (const chunk of req) {
    size += chunk.length;
    if (size > limit) throw new TooLarge(`body over ${limit} bytes`);
    chunks.push(chunk);
  }
  return Buffer.concat(chunks).toString("utf8");
};

import { createServer, type ServerResponse } from "node:http";
import { readBody, TooLarge } from "./body.js";

const comments: string[] = [];
const send = (res: ServerResponse, status: number, body: unknown) =>
  void res.writeHead(status, { "content-type": "application/json" }).end(JSON.stringify(body));

export const server = createServer(async (req, res) => {
  const url = new URL(req.url ?? "/", "http://localhost");
  const route = `${req.method} ${url.pathname}`;
  try {
    if (route === "GET /health") return void res.end("ok");
    if (route === "GET /v1/comments") return send(res, 200, { comments });
    if (route === "POST /v1/comments") {
      const { text } = JSON.parse(await readBody(req)) as { text: string };
      comments.push(text);
      return send(res, 201, { count: comments.length });
    }
    return send(res, 404, { error: "not found" });
  } catch (error) {
    if (error instanceof TooLarge) return send(res, 413, { error: error.message });
    if (error instanceof SyntaxError) return send(res, 400, { error: "body is not JSON" });
    console.error(route, "failed");
    return send(res, 500, { error: "internal" });
  }
});

